   285	/// Project daemon sessions into the compact metadata used by the Island.
   286	pub(crate) fn derive_island_sessions(
   287	    sessions: &[SessionSummary],
   288	    projects: &[ProjectInfo],
   289	    focused_id: Option<&str>,
   290	) -> Vec<IslandSession> {
   291	    let mut items: Vec<_> = sessions
   292	        .iter()
   293	        .map(|session| {
   294	            let root = session_root(session).to_string();
   295	            let project = session
   296	                .owning_project
   297	                .as_ref()
   298	                .map(|owner| {
   299	                    if owner.name.trim().is_empty() {
   300	                        owner.id.clone()
   301	                    } else {
   302	                        owner.name.trim().to_string()
   303	                    }
   304	                })
   305	                .or_else(|| {
   306	                    project_for_root(projects, &root).map(|project| {
   307	                        if project.name.trim().is_empty() {
   308	                            project.id.clone()
   309	                        } else {
   310	                            project.name.trim().to_string()
   311	                        }
   312	                    })
   313	                });
   314	            let (origin, title) = split_origin(&session.title);
   315	            let is_focused = focused_id == Some(session.id.as_str());
   316	            let priority = if is_focused {
   317	                IslandPriority::Focused
   318	            } else if recently_updated(&session.updated_at) {
   319	                IslandPriority::Recent
   320	            } else {
   321	                IslandPriority::Background
   322	            };
