   384	                .as_deref()
   385	                .and_then(|project| fuzzy_score(query, project));
   386	
   387	            // Match category is a strict tier; fuzzy score only orders items
   388	            // inside a tier, so a long fuzzy title can never outrank an exact
   389	            // project (and metadata can never outrank a title/project match).
   390	            let (tier, mut score) = if title == query_lower {
   391	                (6, title_score.unwrap_or(document_score))
   392	            } else if title.starts_with(&query_lower) {
   393	                (5, title_score.unwrap_or(document_score))
   394	            } else if project.as_deref() == Some(query_lower.as_str()) {
   395	                (4, project_score.unwrap_or(document_score))
   396	            } else if project
   397	                .as_deref()
   398	                .is_some_and(|project| project.starts_with(&query_lower))
   399	            {
   400	                (3, project_score.unwrap_or(document_score))
   401	            } else if let Some(title_score) = title_score {
   402	                (2, title_score)
   403	            } else if let Some(project_score) = project_score {
   404	                (1, project_score)
   405	            } else {
   406	                (0, document_score)
   407	            };
   408	            score += match item.priority {
   409	                IslandPriority::Focused => 2.0,
   410	                IslandPriority::Recent => 1.0,
   411	                IslandPriority::Background => 0.0,
   412	            };
   413	            Some((tier, score, index, item.clone()))
   414	        })
   415	        .collect();
   416	
   417	    scored.sort_by(|a, b| {
   418	        b.0.cmp(&a.0)
   419	            .then_with(|| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal))
   420	            .then_with(|| a.2.cmp(&b.2))
   421	            .then_with(|| a.3.id.cmp(&b.3.id))
   422	    });
   423	    scored
   424	        .into_iter()
   425	        .map(|(_, _, _, item)| IslandResult::Session(item))
   426	        .collect()
   427	}
