   447	fn next_index(index: usize, len: usize) -> usize {
   448	    if len == 0 {
   449	        0
   450	    } else {
   451	        (index + 1) % len
   452	    }
   453	}
   454	
   455	fn previous_index(index: usize, len: usize) -> usize {
   456	    if len == 0 {
   457	        0
   458	    } else {
   459	        (index + len - 1) % len
   460	    }
   461	}
