   309	                        } else {
   310	                            project.name.trim().to_string()
   311	                        }
   312	                    })
   313	                });
   314	            let (origin, title) = split_origin(&session.title);
   315	            let is_focused = focused_id == Some(session.id.as_str());
   316	            let priority = if is_focused {
   317	                IslandPriority::Focused
   318	            } else if recently_updated(&session.updated_at) {
   319	                IslandPriority::Recent
   320	            } else {
   321	                IslandPriority::Background
   322	            };
   323	
   324	            IslandSession {
   325	                id: session.id.clone(),
   326	                title,
   327	                project,
   328	                cwd: root,
   329	                branch: session.git_branch.clone().filter(|value| !value.is_empty()),
   330	                origin,
   331	                updated_at: session.updated_at.clone(),
   332	                turn_count: session.turn_count,
   333	                is_focused,
   334	                priority,
   335	            }
   336	        })
   337	        .collect();
   338	
   339	    items.sort_by(|a, b| {
   340	        b.is_focused
   341	            .cmp(&a.is_focused)
   342	            .then_with(|| b.updated_at.cmp(&a.updated_at))
   343	            .then_with(|| a.title.to_lowercase().cmp(&b.title.to_lowercase()))
   344	            .then_with(|| a.id.cmp(&b.id))
   345	    });
   346	    items
   347	}
