   349	/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
   350	pub(crate) fn island_search_text(item: &IslandSession) -> String {
   351	    let state = match item.priority {
   352	        IslandPriority::Focused => "focused",
   353	        IslandPriority::Recent => "recent",
   354	        IslandPriority::Background => "background",
   355	    };
   356	    let project = item.project.as_deref().unwrap_or_default();
   357	    let branch = item.branch.as_deref().unwrap_or_default();
   358	    let origin = item.origin.as_deref().unwrap_or_default();
   359	    format!(
   360	        "{} {} project:{} {} {} {} {} {} turns",
   361	        item.title, project, project, item.cwd, branch, origin, state, item.turn_count
   362	    )
   363	    .to_lowercase()
   364	}
