   463	#[component]
   464	pub fn Island(
   465	    daemon: Daemon,
   466	    mode: RwSignal<IslandMode>,
   467	    focus_request: RwSignal<u64>,
   468	    on_open: Callback<IslandMode>,
   469	) -> impl IntoView {
   470	    let query = RwSignal::new(String::new());
   471	    let selected_index = RwSignal::new(0usize);
   472	    let previous_mode = RwSignal::new(IslandMode::Closed);
   473	    let previous_focus = StoredValue::new_local(None::<web_sys::HtmlElement>);
   474	    let last_focus_request = RwSignal::new(0u64);
   475	    let recency_tick = RwSignal::new(0u64);
   476	    let expanded_attention = RwSignal::new(None::<String>);
   477	    let input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
   478	    let chip_ref: NodeRef<leptos::html::Button> = NodeRef::new();
   479	    let popover_ref: NodeRef<leptos::html::Section> = NodeRef::new();
   480	
   481	    #[cfg(target_arch = "wasm32")]
   482	    let recency_interval =
   483	        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(60_000, move || {
   484	            recency_tick.update(|tick| *tick = tick.wrapping_add(1))
   485	        }));
   486	    #[cfg(target_arch = "wasm32")]
   487	    on_cleanup(move || drop(recency_interval));
   488	
   489	    #[cfg(target_arch = "wasm32")]
   490	    let attention_interval = {
   491	        let daemon = daemon.clone();
   492	        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(3_000, move || {
   493	            daemon.fetch_attention();
   494	        }))
   495	    };
   496	    #[cfg(target_arch = "wasm32")]
   497	    on_cleanup(move || drop(attention_interval));
   498	
   499	    let session_list = daemon.session_list;
   500	    let request_list = daemon.request_list;
   501	    let permission_list = daemon.permission_list;
   502	    let projects = daemon.projects;
   503	    let focused_id = daemon.session_id;
   504	    let daemon = StoredValue::new(daemon);
   505	
   506	    // The closed chip is an ambient session surface, not merely an overlay
   507	    // trigger. Prime its catalogue on mount so a restored focused session and
   508	    // recent count render without requiring the operator to open Search first.
   509	    // Opening still refreshes both sources below to avoid stale browse results.
   510	    {
   511	        let daemon = daemon.get_value();
   512	        daemon.fetch_sessions();
   513	        daemon.fetch_projects();
   514	        daemon.fetch_attention();
   515	    }
   516	
   517	    let sessions = Memo::new(move |_| {
   518	        let _ = recency_tick.get();
   519	        derive_island_sessions(
   520	            &session_list.get(),
   521	            &projects.get(),
   522	            focused_id.get().as_deref(),
   523	        )
   524	    });
   525	    let attention_items = Memo::new(move |_| {
   526	        derive_attention_items(&request_list.get(), &permission_list.get(), &sessions.get())
   527	    });
   528	    let needs_human_count = Memo::new(move |_| compact_attention_counts(&attention_items.get()).0);
   529	    let running_count = Memo::new(move |_| compact_attention_counts(&attention_items.get()).1);
   530	    let results = Memo::new(move |_| {
   531	        let mut matches = search_island(&query.get(), &sessions.get());
   532	        if mode.get() == IslandMode::Search {
   533	            matches.truncate(20);
   534	        }
   535	        matches
   536	    });
   537	
   538	    Effect::new(move |_| {
   539	        let next = mode.get();
   540	        let request = focus_request.get();
   541	        let previous = previous_mode.get_untracked();
   542	        let previous_request = last_focus_request.get_untracked();
   543	        if next != IslandMode::Closed && previous == IslandMode::Closed {
   544	            let active = web_sys::window()
   545	                .and_then(|window| window.document())
   546	                .and_then(|document| document.active_element())
   547	                .and_then(|element| element.dyn_into::<web_sys::HtmlElement>().ok());
   548	            previous_focus.set_value(active);
   549	            query.set(String::new());
   550	            selected_index.set(0);
   551	            expanded_attention.set(None);
   552	            let daemon = daemon.get_value();
   553	            daemon.fetch_sessions();
   554	            daemon.fetch_projects();
   555	            daemon.fetch_attention();
   556	        }
   557	        let should_focus = next != IslandMode::Closed
   558	            && (previous == IslandMode::Closed || next != previous || request != previous_request);
   559	        if should_focus {
   560	            request_animation_frame(move || {
   561	                if let Some(input) = input_ref.get() {
   562	                    let _ = input.focus();
