   636	            return;
   637	        }
   638	        if key == "Tab" {
   639	            // Phase 2 adds real disclosure/action controls. Keep them inside the
   640	            // modal focus loop while leaving session rows on the combobox's
   641	            // active-descendant path.
   642	            event.prevent_default();
   643	            let mut focusable = Vec::<web_sys::HtmlElement>::new();
   644	            if let Some(popover) = popover_ref.get() {
