   654	                        }
   655	                    }
   656	                }
   657	            }
   658	            if focusable.is_empty() {
   659	                if let Some(input) = input_ref.get() {
   660	                    let _ = input.focus();
   661	                }
   662	                return;
   663	            }
   664	            let current = event
   665	                .target()
   666	                .and_then(|target| target.dyn_into::<web_sys::Node>().ok());
   667	            let current_index = focusable
   668	                .iter()
   669	                .position(|element| {
   670	                    element
   671	                        .clone()
   672	                        .unchecked_into::<web_sys::Node>()
   673	                        .is_same_node(current.as_ref())
